+import type {SessionCursor} from '../../types/sessionStore.js';

 const MAX_CONTENT_LENGTH = 10000;
+const MAX_SESSION_ID_LENGTH = 128;

 interface ValidationSuccess {
   valid: true;
@@ -30,6 +32,8 @@ export function validateMessage(payload: unknown): ValidationResult {
       return validateUserMessage(message);
     case 'ping':
       return validatePingMessage(message);
+    case 'list_sessions':
+      return validateListSessionsMessage(message);
     default:
       return {valid: false, error: `Unknown message type: ${message.type}`};
   }
@@ -72,3 +76,44 @@ function validatePingMessage(message: Record<string, unknown>): ValidationResult
     },
   };
 }
+
+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const data: ListSessionsMessage = {type: 'list_sessions'};
+
+  if (message.limit !== undefined) {
+    const limit = parseLimit(message.limit);
+    if (limit === null) return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
+    data.limit = limit;
+  }
+
+  if (message.before !== undefined) {
+    const before = parseCursor(message.before);
+    if (!before) return {valid: false, error: 'list_sessions before must have a valid updatedAt and sessionId'};
+    data.before = before;
+  }
+
+  return {valid: true, data};
+}
+
+function parseLimit(raw: unknown): number | null {
+  if (typeof raw !== 'number' || !Number.isInteger(raw)) return null;
+  return raw >= 0 ? raw : null;
+}
+
+function parseCursor(raw: unknown): SessionCursor | null {
+  if (typeof raw !== 'object' || raw === null) return null;
+  const cursor = raw as Record<string, unknown>;
+  if (!validSessionId(cursor.sessionId) || !validCursorTime(cursor.updatedAt)) return null;
+  return {updatedAt: cursor.updatedAt, sessionId: cursor.sessionId};
+}
+
+function validSessionId(value: unknown): value is string {
+  if (typeof value !== 'string') return false;
+  return value.length >= 1 && value.length <= MAX_SESSION_ID_LENGTH;
+}
+
+function validCursorTime(value: unknown): value is string | number {
+  if (typeof value === 'number') return Number.isFinite(value);
+  if (typeof value === 'string') return Number.isFinite(Date.parse(value));
+  return false;
+}
