    const sessionStore: SessionStore = {
      create: (sessionId, userId) => ({sessionId, userId, entries: []}),
      get: () => undefined,
      delete: () => true,
      count: () => 0,
      clear: () => undefined,
      listFor: userId => {
        seen.push(userId);
        return [];
      },
    };
    const hal = createServer({
      app: (() => undefined) as unknown as Express,
      wsAuth: jest.fn() as unknown as WsAuthenticator,
      sessionStore,
      orchestrator: {} as ChatOrchestrator,
    });
    const listeners: Record<string, (arg?: unknown) => void> = {};
    const ws = {
      userId: 'u1',
      isAlive: true,
      send: () => undefined,
      on: (event: string, listener: (arg?: unknown) => void) => {
        listeners[event] = listener;
      },
      pause: () => undefined,
      resume: () => undefined,
      close: () => undefined,
    } as unknown as ExtWebSocket;

    hal.wss.emit('connection', ws);
    await settle();
    listeners['message']?.(JSON.stringify({type: 'list_sessions'}));
    await settle();
    hal.wss.emit('close');

    expect(seen).toEqual(['u1']);
  });
