import {WebSocket} from 'ws';
import type {SessionEntry} from '../../types/session.js';
import type {ChatSession} from '../../types/session.js';
import type {SessionStore} from '../../types/sessionStore.js';
import {ErrorCodes} from '../../types/messages.js';
import type {OutgoingMessage} from '../../types/messages.js';
import type {MessageChunk} from '../../types/ai.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import {sendError, sendUpsert, sendDelta, sendCommit, sendSkip, sendStreamEnd, sendJson} from './sender.js';
import {validateMessage} from './validation.js';
import {appendEntry, appendDelta, commitEntry, suppressEntry, closeOpenEntries} from './sessionMutations.js';
import {log} from '../../shared/logger.js';

interface StreamState {
  thinkingIndex: number | null;
  assistantIndex: number | null;
  isSuppressed: boolean;
}

// One chain per session, discarded once idle so a store that evicts sessions does not leak entries here.
const sessionQueues = new WeakMap<ChatSession, Promise<void>>();

function enqueueForSession(session: ChatSession, task: () => Promise<void>): Promise<void> {
  const previous = sessionQueues.get(session) ?? Promise.resolve();
  const next = previous.then(task);
  const settled = next.finally(() => {
    if (sessionQueues.get(session) === settled) sessionQueues.delete(session);
  });
  sessionQueues.set(session, settled);
  return next;
}

export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
  return async function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    if (!validation.valid) {
      if (isUserMessageAttempt(rawMessage)) {
        return enqueueForSession(session, async () => {
          if (signal?.aborted) return;
          rejectWithStreamEnd(ws, validation.error);
        });
      }
      sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
      return;
    }

    const message = validation.data;

    switch (message.type) {
      case 'ping':
        handlePing(ws, message.timestamp);
        return;

      case 'list_sessions':
        await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before});
        return;

      case 'user_message':
        return enqueueForSession(session, () => {
          if (signal?.aborted) return Promise.resolve();
          return handleUserMessage(ws, session, message.content, orchestrator, signal);
        });
    }
  };
}
